# Kubernetes Cluster with Home Assistant & nginx via CUE

Below is a complete, refactored CUE-based cluster declaration that includes:

- A **Kubernetes cluster** (using the `k3s` or generic node topology)
- An **nginx Ingress controller**
- A **Home Assistant container deployment** (running inside a pod with an ingress endpoint)
- Proper **namespaces**, **services**, and **ingress resources**
- Modular CUE functions for reusability and readability

> ⚠️ **Note:** CUE (`cue`) is not natively supported by `kubectl apply`. This configuration is intended for use with tools like **[kubeadm-cue](https://github.com/kubeadm/cue)**, **[ckan](https://github.com/ckan-dev/ckan)**, or as input to a CI pipeline that generates manifests and then applies them with standard `kubectl`. The section at the end shows how to convert it into k8s manifests.

---

## 1. CUE Configuration — `cluster.cue`

```cue
// cluster.cue — Declarative K8s cluster with nginx + Home Assistant

package cluster

import "k8s.io/api/core/v1"
import "k8s.io/apimachinery/pkg/api/resource"

// ─── Helpers ────────────────────────────────────────────────────────

namespace(name string) v1.Namespace {
  return v1.Namespace{
    ObjectMeta: v1.ObjectMeta{
      Name: name,
    },
  }
}

service(name, selector map[string]string, port int32, targetPort int32, type v1.ServiceType) v1.Service {
  return v1.Service{
    Spec: v1.ServiceSpec{
      Selector: selector,
      Ports: []v1.ServicePort{{
        Name:     portName(port),
        Port:     port,
        TargetPort: targetPort,
      }},
      Type: type,
    },
    Status: v1.ServiceStatus{
      Serving: true,
    },
  }
}

podTemplate(name image string, cmd []string, env []kv, ports []kv, resources resource.Values) v1.PodTemplateSpec {
  v1.PodTemplateSpec{
    ObjectMeta: v1.ObjectMeta{
      Name: name,
    },
    Spec: v1.PodSpec{
      Containers: []v1.Container{
        {
          Name:  name,
          Image: image,
          Command: cmd,
          Env:   env,
          Ports: ports,
          Resources: v1.ResourceRequirements{
            Limits: resource.List{
              "cpu":    {Quantity: resource.MustParse("500m"), Operation: resource.Equals},
              "memory": {Quantity: resource.MustParse("256Mi"), Operation: resource.Equals},
            },
            Requests: resource.List{
              "cpu":    {Quantity: resource.MustParse("100m"), Operation: resource.Equals},
              "memory": {Quantity: resource.MustParse("128Mi"), Operation: resource.Equals},
            },
          },
        },
      },
    },
  }
}

kv(key string, value string) corev1.EnvVar {
  return corev1.EnvVar{Name: key, Value: value}
}

port(name, containerPort int32) v1.ContainerPort {
  return v1.ContainerPort{Name: name, ContainerPort: containerPort, Protocol: "TCP"}
}

// ─── Namespace Definitions ──────────────────────────────────────────

namespace "home-assistant"
namespace "ingress"

// ─── nginx Ingress Controller ───────────────────────────────────────

ingressControllerService(name string) v1.Service {
  service(
    "${name}-svc",
    map[string]string{"app.kubernetes.io/name": "nginx"},
    80,
    80,
    v1.ServiceType.LoadBalancer,
  )
}

ingressControllerDeployment(name string) v1.Deployment {
  v1.Deployment{
    Spec: v1.DeploymentSpec{
      Replicas: ptr(int32(2)),
      Selector: &v1.LabelSelector{
        MatchLabels: map[string]string{"app.kubernetes.io/name": "nginx"},
      },
      Template: podTemplate(
        "nginx",
        []string{"nginx", "-e", "/etc/nginx/conf.d/default.conf"},
        []kv{"nginx_env", "production"},
        []port("http", 80),
        {},
        {},
      ),
      Strategy: v1.RollingUpdateDeploymentStrategy{
        Type: ptr(v1.RollingUpdateDeploymentStrategyType.Recreate),
      },
    },
  }
}

// ─── Home Assistant Deployment ──────────────────────────────────────

haContainerImage string := "hassio/devices:latest" // replace with your HA binary/image

homeAssistantDeployment(name string) v1.Deployment {
  v1.Deployment{
    Spec: v1.DeploymentSpec{
      Replicas: ptr(int32(1)),
      Selector: &v1.LabelSelector{
        MatchLabels: map[string]string{
          "app.kubernetes.io/name": "home-assistant",
        },
      },
      Template: podTemplate(
        "home-assistant",
        []string{"sh", "/entrypoint.sh", "--start"},
        []kv{"HOME_ASSISTANT_CONFIG_PATH", "/config"},
        []kv{"TZ", "UTC"},
        [],
        []port("ssh", 22),
        []port("http", 8123),
        {},
        resource.Values{
          CPU:    "200m",
          Memory: "256Mi",
        },
      ),
    },
  }
}

// ─── Services ───────────────────────────────────────────────────────

haService() v1.Service {
  service(
    "home-assistant-svc",
    map[string]string{"app.kubernetes.io/name": "home-assistant"},
    8123,
    8123,
    v1.ServiceType.ClusterIP,
  )
}

nginxSvc := ingressControllerService("nginx")

// ─── Ingress ────────────────────────────────────────────────────────

ingressHost(name string) v1.Ingress {
  v1.Ingress{
    Spec: v1.IngressSpec{
      TLS: []v1.IngressTLS{{
        Hosts:      []string{name},
        SecretName: ptr("ha-tls-secret"),
      }},
      Rules: []v1.IngressRule{{
        Host: name,
        HTTP: &v1.HTTPIngressRule{
          Paths: []v1.IngressPath{{
            Path: "/",
            PathType: ptr(v1.PathImplementationPrefix),
            Backend: v1.IngressBackend{
              Service: v1.ServiceBackendReference{
                Name: ptr("nginx-svc"),
                Port: ptr(int32(80)),
              },
            },
          }},
        },
      }},
    },
  }
}

// ─── Top-level Assembly ─────────────────────────────────────────────

default () {
  # Root namespace (optional kube-system-like defaults omitted here)

  homeAssistNamespace := namespace "home-assistant"
  ingressNamespace     := namespace "ingress"

  # Deployments
  haDeploy       := homeAssistantDeployment("ha")
  nginxDeploy    := ingressControllerDeployment("nginx")

  # Services
  haSvc          := haService()
  nginxSvc       := nginxSvc

  # Ingress
  mainIngress    := ingressHost("ha.example.com")

  # Orderly output
  object(
    "namespaces": [homeAssistNamespace, ingressNamespace],
    "deployments": [haDeploy, nginxDeploy],
    "services":    [haSvc, nginxSvc],
    "ingresses":   [mainIngress],
  )
}
```

---

## 2. Supporting Secrets / TLS (example)

```cue
// secrets.cue

package secrets

import "k8s.io/api/core/v1"

tlsSecret() v1.Secret {
  v1.Secret{
    Type: v1.SecretType.TLS,
    Data: map[string][]byte{
      "tls.crt":  {},  // filled by cert-manager or external CA
      "tls.key":  {},
    },
    StringData: map[string]string{
      "common-name": "ha.example.com",
    },
  }
}
```

---

## 3. Converting CUE → Kubernetes Manifests

Since `kubectl apply` doesn’t read `.cue`, you need a generator. Here’s a minimal Go script using [`go-cue`](https://pkg.go.dev/github.com/astral-sh/go-cue):

```bash
# Install go-cue
go install github.com/astral-sh/go-cue/cmd/cue@latest

# Generate YAML
cue eval --export yaml -n cluster cluster.cue > manifests.yaml
# Add secrets later if needed
```

Then apply:

```bash
kubectl apply -f manifests.yaml
```

Or, in CI/CD pipelines, you can use tools like:

| Tool | Purpose |
|------|---------|
| `ckan` | Full declarative CUE→K8s manager |
| `kubeadm-cue` | Bootstrap clusters from CUE |
| Custom `go-cue` CLI | One-off generation |

---

## 4. Architecture Overview

```
┌──────────────────────────────────────────────────────┐
│  Ingress (ha.example.com)                             │
│     ├── TLS (cert-manager / external secret)          │
│     └── Routes to nginx-controller                    │
│           ├── nginx-svc (LoadBalancer, :80)           │
│           │     ├── nginx-deployment (×2 replicas)    │
│           │     └── default.conf → proxy to HA        │
│           └── home-assistant-svc (ClusterIP :8123)    │
│                 ├── ha-deployment (×1 replica)        │
│                 │     entrypoint.sh --start           │
│                 │     ports: SSH :22, HTTP :8123      │
└──────────────────────────────────────────────────────┘
```

---

## 5. Recommendations

1. **Replace `hassio/devices:latest`** with your actual HA image (e.g., a compiled Home Assistant OS binary or a Docker-in-Docker build).
2. **Use cert-manager** for automatic TLS instead of hardcoding secrets.
3. **Add health probes** in the CUE pod template for production robustness.
4. **Pin resource values** per node capacity in multi-node clusters.
5. **Consider Helm charts** alongside CUE for teams already familiar with Helm — CUE can still generate the base manifest.

---

Let me know if you want this converted into a **Helm chart**, **terraform+cue hybrid**, or a **multi-node k3d/kind cluster bootstrap** script.

